ALTER TABLE invoice ADD COLUMN retention_pct DECIMAL(5, 2) DEFAULT 0 NOT NULL;
ALTER TABLE invoice ADD COLUMN retention_released_on DATE;
-- A credit note may be for more than its original still owes. What the original took of it is kept in
-- credit_applied (credit_retention of that cleared retention it held back); the rest is held on the
-- client's account as a payment naming the credit note (credit_note), which cannot be reversed.
ALTER TABLE invoice ADD COLUMN credit_applied DECIMAL(19, 2);
ALTER TABLE invoice ADD COLUMN credit_retention DECIMAL(19, 2) DEFAULT 0 NOT NULL;
UPDATE invoice SET credit_applied = credit_total WHERE credit_total IS NOT NULL;
ALTER TABLE payment ADD COLUMN credit_note BIGINT;
-- A draft spread over monthly instalments: how many (2 to 24; null when there is no plan) and the
-- annual interest rate (0 to 30, up to two decimals) the schedule is worked out at.
ALTER TABLE invoice ADD COLUMN instalments INT;
ALTER TABLE invoice ADD COLUMN instalment_rate DECIMAL(5, 2) DEFAULT 0 NOT NULL;
-- The currency a client is billed in (USD, EUR, GBP, JPY or CHF); clients are billed in US dollars by default.
ALTER TABLE client ADD COLUMN currency VARCHAR(3) DEFAULT 'USD' NOT NULL;
