426	    /**
427	     * The plan's schedule at the tax rate, an ordinary loan of the grand total; empty when there is no
428	     * plan. With the monthly rate i (the annual rate / 12 / 100) the instalment is P x i / (1 - (1 +
429	     * i)^-n), or P / n at 0%, rounded half up to the cent. Each month's interest is the balance still
430	     * owed x i, rounded half up to the cent, and its principal the instalment less the interest; the
431	     * last instalment pays off the whole balance left plus its interest, so the schedule ends at zero.
432	     * Instalment k falls due k months after the issue date, on the same day (the month's last day when
433	     * it is shorter).
434	     */
435	    public List<Instalment> schedule(BigDecimal taxRate) {
436	        if (!hasPlan()) {
437	            return List.of();
438	        }
439	        MathContext mc = MathContext.DECIMAL128;
440	        BigDecimal principal = total(taxRate);
441	        BigDecimal i = instalmentRate.divide(BigDecimal.valueOf(1200), mc);
442	        int n = instalments;
443	        BigDecimal payment;
444	        if (i.signum() == 0) {
445	            payment = principal.divide(BigDecimal.valueOf(n), scale(), RoundingMode.HALF_UP);
446	        } else {
447	            BigDecimal growth = BigDecimal.ONE.add(i).pow(n, mc);
448	            payment = principal.multiply(i).multiply(growth)
449	                    .divide(growth.subtract(BigDecimal.ONE), mc).setScale(scale(), RoundingMode.HALF_UP);
450	        }
451	        List<Instalment> schedule = new ArrayList<>(n);
452	        BigDecimal balance = principal.setScale(scale(), RoundingMode.HALF_UP);
453	        for (int k = 1; k <= n; k++) {
454	            BigDecimal interest = balance.multiply(i).setScale(scale(), RoundingMode.HALF_UP);
455	            BigDecimal paid = k == n ? balance.add(interest) : payment;
456	            BigDecimal repaid = paid.subtract(interest);
457	            balance = balance.subtract(repaid);
458	            LocalDate due = issueDate == null ? null : issueDate.plusMonths(k);
459	            schedule.add(new Instalment(k, due, paid, interest, repaid, balance));
460	        }
461	        return schedule;
462	    }
