464	    /** The plan total at the tax rate: the sum of the instalments; null when there is no plan. */
465	    public BigDecimal planTotal(BigDecimal taxRate) {
466	        if (!hasPlan()) {
467	            return null;
468	        }
469	        return schedule(taxRate).stream().map(Instalment::payment).reduce(zero(), BigDecimal::add);
470	    }
