472	    /**
473	     * Each instalment of the plan at the tax rate once the given amount has been paid, on the given
474	     * day: payments (with what credit notes took off and anything written off) pay the instalments in
475	     * order, each paid off before the next. An instalment not paid off more than {@link #GRACE_DAYS}
476	     * days after its due date is overdue; empty when there is no plan.
477	     */
478	    public List<Instalment.Progress> instalmentProgress(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
479	        List<Instalment.Progress> progress = new ArrayList<>();
480	        BigDecimal left = paid.add(getCredited()).add(writtenOff(paid, taxRate));
481	        for (Instalment instalment : schedule(taxRate)) {
482	            BigDecimal part = left.min(instalment.payment()).max(BigDecimal.ZERO).setScale(scale(), RoundingMode.HALF_UP);
483	            left = left.subtract(part);
484	            BigDecimal unpaid = instalment.payment().subtract(part);
485	            Instalment.Status status;
486	            if (unpaid.signum() <= 0) {
487	                status = Instalment.Status.PAID;
488	            } else if (instalment.dueDate() != null && today.isAfter(instalment.dueDate().plusDays(GRACE_DAYS))) {
489	                status = Instalment.Status.OVERDUE;
490	            } else if (part.signum() > 0) {
491	                status = Instalment.Status.PART_PAID;
492	            } else {
493	                status = Instalment.Status.DUE;
494	            }
495	            progress.add(new Instalment.Progress(instalment, part, unpaid, status));
496	        }
497	        return progress;
498	    }
