500	    /**
501	     * What is overdue at the tax rate once the given amount has been paid, on the given day: for a plan,
502	     * only what is unpaid on its overdue instalments; otherwise all that is due when it is overdue.
503	     */
504	    public BigDecimal overdueAmount(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
505	        if (statusWhenPaid(paid, taxRate, today) != InvoiceStatus.OVERDUE) {
506	            return zero();
507	        }
508	        if (!hasPlan()) {
509	            return amountDue(paid, taxRate);
510	        }
511	        return instalmentProgress(paid, taxRate, today).stream()
512	                .filter(p -> p.status() == Instalment.Status.OVERDUE).map(Instalment.Progress::unpaid)
513	                .reduce(zero(), BigDecimal::add);
514	    }
