604	
605	    /**
606	     * The status on the given day once the given amount has been paid against the grand total at the
607	     * tax rate: a sent invoice with something still due more than {@link #GRACE_DAYS} days after its
608	     * due date is overdue, part paid or not. Held retention is never due, so never makes it overdue;
609	     * released retention is due {@link #RETENTION_DUE_DAYS} days after its release, and payments go to
610	     * the rest of the invoice before it. An invoice spread over instalments is instead overdue when any
611	     * of its instalments is (see {@link #instalmentProgress}).
612	     */
613	    public InvoiceStatus statusWhenPaid(BigDecimal paid, BigDecimal taxRate, LocalDate today) {
614	        return statusWhenPaid(paid, null, taxRate, today);
615	    }
616	
617	    /**
618	     * As {@link #statusWhenPaid(BigDecimal, BigDecimal, LocalDate)}, but a fully paid invoice whose
619	     * paid date (null when not known) is after its due date is paid late.
620	     */
621	    public InvoiceStatus statusWhenPaid(BigDecimal paid, LocalDate paidOn, BigDecimal taxRate, LocalDate today) {
622	        if (status != InvoiceStatus.SENT) {
623	            return status;
624	        }
625	        BigDecimal amountDue = amountDue(paid, taxRate);
626	        boolean due = amountDue.signum() > 0;
627	        BigDecimal retentionDue = amountDue.min(retentionReleased(taxRate)).max(BigDecimal.ZERO);
628	        boolean restDue = amountDue.subtract(retentionDue).signum() > 0;
629	        if (hasPlan()) {
630	            if (due && instalmentProgress(paid, taxRate, today).stream()
631	                    .anyMatch(p -> p.status() == Instalment.Status.OVERDUE)) {
632	                return InvoiceStatus.OVERDUE;
633	            }
634	        } else if (restDue && dueDate != null && today.isAfter(dueDate.plusDays(GRACE_DAYS))) {
635	            return InvoiceStatus.OVERDUE;
636	        }
637	        if (retentionDue.signum() > 0 && today.isAfter(retentionDueDate().plusDays(GRACE_DAYS))) {
638	            return InvoiceStatus.OVERDUE;
639	        }
640	        if (!due && retentionHeld(taxRate).signum() > 0) {
641	            return InvoiceStatus.RETENTION_HELD;
642	        }
643	        if (paid.signum() <= 0) {
644	            return !due && getCredited().signum() > 0 ? InvoiceStatus.CREDITED : status;
645	        }
646	        if (due) {
647	            return InvoiceStatus.PART_PAID;
648	        }
649	        return paidOn != null && dueDate != null && paidOn.isAfter(dueDate) ? InvoiceStatus.PAID_LATE
650	                : InvoiceStatus.PAID;
651	    }
652	
653	    /**
654	     * The date the invoice was fully paid: the date of the payment that cleared its grand total at the
655	     * tax rate, taking the parts of payments (not reversed) in the order they were applied (credit used
656	     * counts on the day it was applied); null while something is still due or retention is held.
657	     */
658	    public LocalDate paidOn(List<Payment> payments, BigDecimal taxRate) {
659	        BigDecimal total = payable(taxRate);
660	        if (status != InvoiceStatus.SENT || total.signum() <= 0 || retentionHeld(taxRate).signum() > 0) {
661	            return null;
662	        }
663	        record Part(LocalDate on, Long paymentId, BigDecimal amount) {
664	        }
665	        List<Part> inOrder = payments.stream().filter(p -> !p.isReversed())
666	                .flatMap(p -> p.getAllocations().stream().filter(a -> a.getInvoiceId().equals(id))
667	                        .map(a -> new Part(a.getDate() == null ? p.getDate() : a.getDate(), p.getId(), a.getAmount())))
668	                .sorted(Comparator.comparing(Part::on).thenComparing(Part::paymentId)).toList();
669	        BigDecimal sum = BigDecimal.ZERO;
670	        for (Part p : inOrder) {
671	            sum = sum.add(p.amount());
672	            if (sum.signum() > 0 && isSmallEnoughToWriteOff(total.subtract(sum))) {
673	                return p.on();
674	            }
675	        }
676	        return null;
677	    }
678	
679	    /**
680	     * What is still due once the given amount has been paid: the grand total less it, less what credit
681	     * notes have credited, less the retention still held, less anything written off — so nothing once
682	     * payments leave less than {@link #WRITE_OFF_LIMIT}. A credit note itself has nothing due.
683	     */
684	    public BigDecimal amountDue(BigDecimal paid, BigDecimal taxRate) {
685	        if (isCreditNote()) {
686	            return zero();
687	        }
688	        return payable(taxRate).subtract(paid).subtract(writtenOff(paid, taxRate));
689	    }
690	
691	    /**
692	     * What is written off once the given amount has been paid: when payments leave less than
693	     * {@link #WRITE_OFF_LIMIT} still due, all of what is left; otherwise nothing.
694	     */
695	    public BigDecimal writtenOff(BigDecimal paid, BigDecimal taxRate) {
696	        BigDecimal left = payable(taxRate).subtract(paid);
697	        return !isCreditNote() && paid.signum() > 0 && left.signum() > 0 && isSmallEnoughToWriteOff(left)
698	                ? left.setScale(scale(), RoundingMode.HALF_UP)
699	                : zero();
700	    }
701	
702	    /** The least a part payment may be at the tax rate: {@link #MINIMUM_PART_SHARE} of the grand total. */
703	    public BigDecimal minimumPart(BigDecimal taxRate) {
704	        return total(taxRate).multiply(MINIMUM_PART_SHARE).setScale(scale(), RoundingMode.HALF_UP);
705	    }
706	
707	    /**
708	     * Whether paying the amount on top of what was already paid is too small a part payment: under
709	     * {@link #minimumPart} while leaving something still due (what would be written off counts as settled).
710	     * For a plan the least is instead what is still unpaid on its earliest unpaid instalment.
711	     */
712	    public boolean isTooSmallPart(BigDecimal amount, BigDecimal paid, BigDecimal taxRate) {
713	        if (hasPlan()) {
714	            return amount.compareTo(earliestUnpaid(paid, taxRate)) < 0
715	                    && amountDue(paid.add(amount), taxRate).signum() > 0;
716	        }
717	        return amount.compareTo(minimumPart(taxRate)) < 0 && amountDue(paid.add(amount), taxRate).signum() > 0;
718	    }
719	
720	    /** Adds a line to the end of the invoice. */
721	    public void addLine(InvoiceLine line) {
722	        lines.add(line);
723	    }
724	
725	    /** Whether the invoice has the line with the given id. */
726	    public boolean hasLine(Long lineId) {
727	        return lines.stream().anyMatch(l -> lineId.equals(l.getId()));
728	    }
729	
730	    /**
731	     * Removes the line with the given id; whether the invoice had it. Refused when what is left would
732	     * be less than a fixed discount on the invoice.
733	     */
734	    public boolean removeLine(Long lineId) {
735	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
736	        if (line == null) {
737	            return false;
738	        }
739	        BigDecimal left = subtotal().subtract(line.amount(scale()));
740	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
741	            throw new InvoiceRejectedException("This line cannot be removed: the "
742	                    + currency().format(left) + " left would be less than the "
743	                    + currency().format(discountAmount) + " discount.");
744	        }
745	        lines.remove(line);
746	        return true;
747	    }
748	
749	    /**
750	     * Changes the line with the given id to the given values; whether the invoice had it. Refused when
751	     * the subtotal would then be less than a fixed discount on the invoice.
752	     */
753	    public boolean updateLine(Long lineId, String description, BigDecimal qty, BigDecimal unitPrice,
754	            boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
755	        InvoiceLine line = lines.stream().filter(l -> lineId.equals(l.getId())).findFirst().orElse(null);
756	        if (line == null) {
757	            return false;
758	        }
759	        BigDecimal changed = new InvoiceLine(description, qty, unitPrice, taxExempt, discountPct, taxRate).amount(scale());
760	        BigDecimal left = subtotal().subtract(line.amount(scale())).add(changed);
761	        if (discountAmount.signum() > 0 && left.compareTo(discountAmount) < 0) {
762	            throw new InvoiceRejectedException("This line cannot be changed: the "
763	                    + currency().format(left) + " subtotal would be less than the "
764	                    + currency().format(discountAmount) + " discount.");
765	        }
766	        line.update(description, qty, unitPrice, taxExempt, discountPct, taxRate);
767	        return true;
768	    }
769	
770	    /**
771	     * The sum of the line amounts, each after its own discount and already to the cent — so the subtotal
772	     * matches what a client gets by adding up the lines shown.
773	     */
774	    public BigDecimal subtotal() {
775	        return lines.stream().map(l -> l.amount(scale()))
776	                .reduce(zero(), BigDecimal::add);
777	    }
778	
779	    /**
780	     * The amount taken off: the fixed amount when there is one (never more than the subtotal, should
781	     * lines have been changed since), otherwise the discount percentage of the subtotal, rounded down
782	     * to the cent. When there is a cap, it limits everything taken off — the line discounts plus
783	     * this — so this shrinks to what the line discounts leave under the cap, never below zero.
784	     */
785	    public BigDecimal discount() {
786	        BigDecimal discount = discountAmount.signum() > 0
787	                ? discountAmount.min(subtotal()).setScale(scale(), RoundingMode.HALF_UP)
788	                : subtotal().multiply(discountPct).divide(BigDecimal.valueOf(100)).setScale(scale(), RoundingMode.DOWN);
789	        if (discountCap == null) {
790	            return discount;
791	        }
792	        BigDecimal lineDiscounts = lines.stream().map(l -> l.discount(scale()))
793	                .reduce(zero(), BigDecimal::add);
794	        BigDecimal left = discountCap.setScale(scale(), RoundingMode.HALF_UP).subtract(lineDiscounts).max(zero());
795	        return discount.min(left);
796	    }
797	
798	    /**
799	     * Each line's share of the discount, in the order of the lines. The discount's cents are split in
800	     * proportion to the line amounts: each line first gets the whole cents of its exact share
801	     * (rounded down), then the cents left over go one each to the lines with the largest leftover
802	     * fractions; between equal fractions the cent goes to the line with the larger amount, and between
803	     * equal amounts too to the lower line id. The shares add up to the discount.
804	     */
805	    public List<BigDecimal> discountShares() {
806	        BigInteger discountCents = discount().movePointRight(scale()).toBigIntegerExact();
807	        BigInteger subtotalCents = subtotal().movePointRight(scale()).toBigIntegerExact();
808	        int n = lines.size();
809	        BigInteger[] shares = new BigInteger[n];
810	        BigInteger[] leftovers = new BigInteger[n];
811	        BigInteger given = BigInteger.ZERO;
812	        for (int i = 0; i < n; i++) {
813	            if (subtotalCents.signum() == 0) {
814	                shares[i] = BigInteger.ZERO;
815	                leftovers[i] = BigInteger.ZERO;
816	            } else {
817	                // The exact share is discount * amount / subtotal; all fractions share the subtotal
818	                // as denominator, so the remainders compare as the fractions do.
819	                BigInteger[] qr = discountCents.multiply(lines.get(i).amount(scale()).movePointRight(scale()).toBigIntegerExact())
820	                        .divideAndRemainder(subtotalCents);
821	                shares[i] = qr[0];
822	                leftovers[i] = qr[1];
823	            }
824	            given = given.add(shares[i]);
825	        }
826	        List<Integer> order = new ArrayList<>();
827	        for (int i = 0; i < n; i++) {
828	            order.add(i);
829	        }
830	        order.sort(Comparator.<Integer, BigInteger>comparing(i -> leftovers[i]).reversed()
831	                .thenComparing(Comparator.<Integer, BigDecimal>comparing(i -> lines.get(i).amount(scale())).reversed())
832	                .thenComparing(i -> lines.get(i).getId(), Comparator.nullsLast(Comparator.naturalOrder())));
833	        int left = discountCents.subtract(given).intValueExact();
834	        for (int k = 0; k < left; k++) {
835	            int i = order.get(k);
836	            shares[i] = shares[i].add(BigInteger.ONE);
837	        }
838	        List<BigDecimal> result = new ArrayList<>(n);
839	        for (BigInteger share : shares) {
840	            result.add(new BigDecimal(share, scale()));
841	        }
842	        return result;
843	    }
844	
845	    /**
846	     * Each line's tax, in the order of the lines: the line's own rate (a percentage), or the given
847	     * workspace rate when it has none, on the line's amount less its share of the discount, rounded
848	     * half up to the cent. Tax-exempt lines, and every line of a tax-exempt client, have no tax.
849	     */
850	    public List<BigDecimal> lineTaxes(BigDecimal taxRate) {
851	        List<BigDecimal> shares = discountShares();
852	        List<BigDecimal> taxes = new ArrayList<>(lines.size());
853	        for (int i = 0; i < lines.size(); i++) {
854	            InvoiceLine line = lines.get(i);
855	            taxes.add(clientTaxExempt || line.isTaxExempt() ? zero()
856	                    : line.amount(scale()).subtract(shares.get(i)).multiply(line.taxRate(taxRate)).divide(BigDecimal.valueOf(100))
857	                            .setScale(scale(), RoundingMode.HALF_UP));
858	        }
859	        return taxes;
860	    }
861	
862	    /** The tax charged at the given rate (a percentage): the sum of the line taxes. */
863	    public BigDecimal tax(BigDecimal taxRate) {
864	        return lineTaxes(taxRate).stream().reduce(zero(), BigDecimal::add);
865	    }
866	
867	    /** The grand total: the subtotal less the discount, plus tax at the given rate. */
868	    public BigDecimal total(BigDecimal taxRate) {
869	        return subtotal().subtract(discount()).add(tax(taxRate));
870	    }
871	}
