122	    /**
123	     * An invoice for a client with payment terms is due that many days after it is issued; otherwise
124	     * as {@link #dueDateFor(LocalDate)}.
125	     */
126	    private LocalDate dueDateFor(Long clientId, LocalDate issued) {
127	        return clients.findById(clientId)
