133	    /** A new invoice is due on the last day of the month after the month it is issued in. */
134	    static LocalDate dueDateFor(LocalDate issued) {
135	        LocalDate nextMonth = issued.plusMonths(1);
136	        return nextMonth.withDayOfMonth(nextMonth.lengthOfMonth());
