164	    @Transactional
165	    public Optional<Invoice> removeLine(Long invoiceId, Long lineId) {
166	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
167	        if (found.isEmpty()) {
168	            return found;
169	        }
170	        Invoice invoice = found.get();
171	        if (!invoice.hasLine(lineId)) {
172	            return Optional.empty();
173	        }
174	        boolean reopened = reopenForChange(invoice, "A paid invoice cannot have lines removed.");
175	        invoice.removeLine(lineId);
176	        invoices.saveAndFlush(invoice);
177	        if (reopened) {
178	            audit.record("INVOICE_REOPENED id=" + invoice.getId());
179	        }
180	        return found;
181	    }
