188	    @Transactional
189	    public Optional<Invoice> updateLine(Long invoiceId, Long lineId, String description, BigDecimal qty,
190	            BigDecimal unitPrice, boolean taxExempt, BigDecimal discountPct, BigDecimal taxRate) {
