271	     */
272	    @Transactional
273	    public Optional<Invoice> setRetention(Long invoiceId, BigDecimal retentionPct) {
274	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
275	        found.ifPresent(invoice -> {
276	            if (invoice.isCreditNote()) {
277	                throw new InvoiceRejectedException("A credit note holds back no retention.");
278	            }
279	            if (!invoice.isDraft()) {
280	                throw new InvoiceRejectedException("Retention can only be set on a draft.");
