291	    /**
292	     * Spreads a draft over the number of monthly instalments at the annual interest rate; empty if no
293	     * such invoice. Both have already been checked; any invoice that is not a draft, a credit note, or
294	     * one holding back retention is refused.
295	     */
296	    @Transactional
297	    public Optional<Invoice> setPlan(Long invoiceId, int instalments, BigDecimal instalmentRate) {
298	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
299	        found.ifPresent(invoice -> {
300	            if (invoice.isCreditNote()) {
