302	            }
303	            if (!invoice.isDraft()) {
304	                throw new InvoiceRejectedException("Only a draft can be spread over instalments.");
305	            }
306	            if (invoice.getRetentionPct().signum() > 0) {
307	                throw new InvoiceRejectedException("An invoice holding back retention cannot also be spread over instalments.");
308	            }
309	            invoice.setPlan(instalments, instalmentRate);
