315	    /**
316	     * Releases the retention held back on a sent invoice today, adding it to the amount due (falling
317	     * due {@link Invoice#RETENTION_DUE_DAYS} days later), and records it in the audit; empty if no such
318	     * invoice. Refused while anything else is still due, or when there is no retention held to release.
319	     */
320	    @Transactional
321	    public Optional<Invoice> releaseRetention(Long invoiceId) {
322	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
323	        found.ifPresent(invoice -> {
324	            if (invoice.isDraft() || invoice.isVoid() || invoice.isCreditNote()) {
325	                throw new InvoiceRejectedException("Retention can only be released on a sent invoice.");
326	            }
327	            BigDecimal rate = taxRate.percent();
328	            BigDecimal held = invoice.retentionHeld(rate);
329	            if (held.signum() <= 0) {
330	                throw new InvoiceRejectedException("There is no retention held to release.");
331	            }
332	            BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), rate);
333	            if (due.signum() > 0) {
334	                throw new InvoiceRejectedException("The retention can only be released once nothing else is due; "
335	                        + invoice.currency().format(due) + " is still due.");
336	            }
337	            invoice.releaseRetention(today.date());
338	            invoices.saveAndFlush(invoice);
339	            audit.record("RETENTION_RELEASED id=" + invoice.getId() + " amount=" + held.toPlainString());
340	        });
341	        return found;
342	    }
