369	    /**
370	     * Sends a draft invoice, issuing it today and making it due on the client's terms (or keeping a due
371	     * date set by hand), and records it in the audit; empty if no such invoice. An invoice already
372	     * sent, with no lines, whose discount needs a reason but has none, or whose due date set by hand is
373	     * before today, is refused.
374	     */
375	    @Transactional
376	    public Optional<Invoice> send(Long invoiceId) {
377	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
378	        found.ifPresent(invoice -> {
379	            if (invoice.isVoid()) {
380	                throw new InvoiceRejectedException("A void invoice cannot be sent.");
381	            }
382	            if (!invoice.isDraft()) {
383	                throw new InvoiceRejectedException("This invoice has already been sent.");
384	            }
385	            if (invoice.getLines().isEmpty()) {
386	                throw new InvoiceRejectedException("Add at least one line before sending the invoice.");
387	            }
388	            if (invoice.isCreditNote()) {
389	                String refusal = creditNoteRefusal(invoice);
390	                if (refusal != null) {
391	                    throw new InvoiceRejectedException(refusal);
392	                }
393	                issue(invoice);
394	                return;
395	            }
396	            if (invoice.discountLacksReason()) {
397	                throw new InvoiceRejectedException(
398	                        "The discount is more than 20% of the subtotal; give it a reason before sending the invoice.");
399	            }
400	            if (invoice.dueDatePassedBy(today.date())) {
401	                throw new InvoiceRejectedException("The due date (" + invoice.getDueDate()
402	                        + ") is already past; set a later due date before sending the invoice.");
403	            }
404	            markSent(invoice);
405	        });
406	        return found;
407	    }
