409	    /**
410	     * Sends each of the client's drafts that has at least one line, lowest id first, as {@link #send}
411	     * would; drafts with no lines, whose discount needs a reason but has none, or whose due date set by
412	     * hand is already past, stay drafts.
413	     */
414	    @Transactional
415	    public void sendAllDrafts(Long clientId) {
416	        invoices.findByClientIdOrderByIdAsc(clientId).stream()
417	                .filter(invoice -> invoice.isDraft() && !invoice.getLines().isEmpty() && !invoice.discountLacksReason()
418	                        && !invoice.dueDatePassedBy(today.date()))
419	                .forEach(invoice -> {
420	                    if (!invoice.isCreditNote()) {
421	                        markSent(invoice);
422	                    } else if (creditNoteRefusal(invoice) == null) {
423	                        issue(invoice);
424	                    }
425	                });
426	    }
