428	    /**
429	     * Why the draft credit note cannot be issued, or null when it can: its original must be a sent
430	     * invoice (not void).
431	     */
432	    private String creditNoteRefusal(Invoice note) {
433	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElse(null);
434	        if (original == null || original.isDraft() || original.isVoid()) {
435	            return "The invoice this credits is not a sent invoice, so the credit note cannot be issued.";
436	        }
437	        return null;
438	    }
