440	    /**
441	     * Issues the draft credit note today and records it in the audit: its grand total comes off what
442	     * its original still owes, then the retention it holds back; any rest is held on the client's
443	     * account as a credit payment dated today, also recorded in the audit.
444	     */
445	    private void issue(Invoice note) {
446	        BigDecimal rate = taxRate.percent();
447	        Invoice original = invoices.findWithLinesById(note.getCreditOf()).orElseThrow();
448	        // Read again what it has been credited: another credit note may just have been issued against it.
449	        entityManager.refresh(original);
450	        BigDecimal total = note.total(rate);
451	        BigDecimal[] taken = original.creditTaken(total, paid(List.of(original)).get(original.getId()), rate);
452	        note.markIssued(today.date(), rate, taken[0], taken[1]);
453	        invoices.saveAndFlush(note);
454	        audit.record("CREDIT_NOTE_ISSUED id=" + note.getId() + " number=" + note.number() + " invoice="
455	                + note.getCreditOf() + " total=" + total.toPlainString());
456	        BigDecimal rest = total.subtract(taken[0]);
457	        if (rest.signum() > 0) {
458	            recordCreditHeld(payments.saveAndFlush(Payment.fromCreditNote(note, rest)));
459	        }
460	    }
461	
462	    /**
463	     * Issues the draft today, due on the client's terms, and records it in the audit; then uses the
464	     * client's credit on it (see {@link #applyCredit}), unless it is spread over instalments, whose
465	     * schedule is dated from the new issue date.
466	     */
467	    private void markSent(Invoice invoice) {
468	        LocalDate issued = today.date();
469	        invoice.markSent(issued, dueDateFor(invoice.getClientId(), issued));
470	        invoices.saveAndFlush(invoice);
471	        audit.record("INVOICE_SENT id=" + invoice.getId() + " number=" + invoice.number()
472	                + " total=" + invoice.total(taxRate.percent()).toPlainString());
473	        if (!invoice.hasPlan()) {
474	            applyCredit(invoice);
475	        }
476	    }
477	
478	    /**
479	     * Uses the client's credit on the invoice just sent, up to what it has due: the oldest payment's
480	     * credit first (lower id first on the same date), each part applied today and recorded in the audit.
481	     */
482	    private void applyCredit(Invoice invoice) {
483	        BigDecimal due = invoice.amountDue(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
484	        LocalDate now = today.date();
485	        boolean used = false;
486	        for (Payment payment : payments.findForClient(invoice.getClientId())) {
487	            if (due.signum() <= 0) {
488	                break;
489	            }
490	            BigDecimal credit = payment.credit();
491	            if (credit.signum() <= 0) {
492	                continue;
493	            }
494	            BigDecimal part = credit.min(due);
495	            payment.apply(invoice.getId(), part, now);
496	            payments.saveAndFlush(payment);
497	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
498	                    + part.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
499	            due = due.subtract(part);
500	            used = true;
501	        }
502	        if (used) {
503	            recordWriteOff(invoice);
504	        }
505	    }
