507	    /**
508	     * Records a deposit of the amount on the date from the client: the whole amount is held on the
509	     * client's account as credit, applied to no invoice, and recorded in the audit; empty if no such
510	     * client. The amount has already been checked; a date after today is refused.
511	     */
512	    @Transactional
513	    public Optional<Payment> recordDeposit(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date) {
514	        Optional<Client> client = clients.findById(clientId);
515	        if (client.isEmpty()) {
516	            return Optional.empty();
517	        }
518	        Currency currency = client.get().getCurrency();
519	        BigDecimal amount = converted(paidAmount, paidIn, currency);
520	        LocalDate now = today.date();
521	        if (date.isAfter(now)) {
522	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
523	        }
524	        Payment payment = payments.saveAndFlush(Payment.deposit(clientId, amount, date).paidIn(paidIn, paidAmount, currency));
525	        audit.record("DEPOSIT_RECORDED id=" + payment.getId() + " client=" + clientId + " amount="
526	                + amount.setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
527	        return Optional.of(payment);
528	    }
