530	    /**
531	     * Refunds the amount of the client's unused credit on the date: the oldest payment's credit first
532	     * (lower id first on the same date), then the next, each part recorded in the audit; empty if no
533	     * such client. The amount has already been checked; a date after today or before a payment it
534	     * would come from, or an amount more than the client's credit, is refused.
535	     */
536	    @Transactional
537	    public Optional<Long> refundCredit(Long clientId, BigDecimal amount, LocalDate date) {
538	        Optional<Client> client = clients.findById(clientId);
539	        if (client.isEmpty()) {
540	            return Optional.empty();
541	        }
542	        Currency currency = client.get().getCurrency();
543	        requireWhole(currency, amount, "The refund");
544	        LocalDate now = today.date();
545	        if (date.isAfter(now)) {
546	            throw new InvoiceRejectedException("The refund date cannot be after today (" + now + ").");
547	        }
548	        List<Payment> from = new ArrayList<>();
549	        List<BigDecimal> parts = new ArrayList<>();
550	        BigDecimal left = amount;
551	        BigDecimal credit = BigDecimal.ZERO;
552	        for (Payment payment : payments.findForClient(clientId)) {
553	            BigDecimal unused = payment.credit();
554	            if (unused.signum() <= 0) {
555	                continue;
556	            }
557	            credit = credit.add(unused);
558	            if (left.signum() <= 0) {
559	                continue;
560	            }
561	            BigDecimal part = unused.min(left);
562	            if (date.isBefore(payment.getDate())) {
563	                throw new InvoiceRejectedException("The refund cannot be dated before the payment of "
564	                        + payment.getDate() + " it would come from.");
565	            }
566	            from.add(payment);
567	            parts.add(part);
568	            left = left.subtract(part);
569	        }
570	        if (left.signum() > 0) {
571	            throw new InvoiceRejectedException("The refund cannot be more than the client's unused credit of "
572	                    + currency.format(credit) + ".");
573	        }
574	        for (int i = 0; i < from.size(); i++) {
575	            Payment payment = from.get(i);
576	            payment.refund(parts.get(i));
577	            payments.saveAndFlush(payment);
578	            audit.record("CREDIT_REFUNDED payment=" + payment.getId() + " amount="
579	                    + parts.get(i).setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
580	        }
581	        return Optional.of(clientId);
582	    }
583	
584	    /** The unused credit of each client that has any, by client id. */
585	    @Transactional(readOnly = true)
586	    public Map<Long, BigDecimal> credits() {
587	        Map<Long, BigDecimal> credits = new HashMap<>();
588	        for (Payment payment : payments.findNotReversed()) {
589	            BigDecimal credit = payment.credit();
590	            if (credit.signum() > 0) {
591	                credits.merge(payment.getClientId(), credit, BigDecimal::add);
592	            }
593	        }
594	        return credits;
595	    }
596	
597	    /**
598	     * Voids a sent invoice with no payments, and records it in the audit; empty if no such invoice. A
599	     * draft, an invoice already void, or one with any payment is refused.
600	     */
601	    @Transactional
602	    public Optional<Invoice> voidInvoice(Long invoiceId) {
603	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
604	        found.ifPresent(invoice -> {
605	            if (invoice.isVoid()) {
606	                throw new InvoiceRejectedException("This invoice is already void.");
607	            }
608	            if (invoice.isDraft()) {
609	                throw new InvoiceRejectedException("A draft cannot be voided; only a sent invoice can.");
610	            }
611	            if (invoice.isCreditNote()) {
612	                throw new InvoiceRejectedException("An issued credit note cannot be voided.");
613	            }
614	            if (invoice.hasCreditNotesIssued()) {
615	                throw new InvoiceRejectedException("An invoice with an issued credit note cannot be voided.");
616	            }
617	            if (!payments.findForInvoice(invoice.getId()).isEmpty()) {
618	                throw new InvoiceRejectedException("An invoice with payments cannot be voided.");
619	            }
620	            invoice.markVoid();
621	            invoices.saveAndFlush(invoice);
622	            audit.record("INVOICE_VOIDED id=" + invoice.getId() + " number=" + invoice.number());
623	        });
624	        return found;
625	    }
626	
627	    /** The payments made to the invoice, oldest first, with their allocations. */
628	    @Transactional(readOnly = true)
629	    public List<Payment> payments(Long invoiceId) {
630	        return payments.findForInvoice(invoiceId);
631	    }
632	
633	    /** The date each fully paid invoice was paid (see {@link Invoice#paidOn}); an invoice not fully paid is left out. */
634	    @Transactional(readOnly = true)
635	    public Map<Long, LocalDate> paidOn(List<Invoice> list) {
636	        Map<Long, LocalDate> paidOn = new HashMap<>();
637	        if (list.isEmpty()) {
638	            return paidOn;
639	        }
640	        List<Payment> found = payments.findForInvoices(list.stream().map(Invoice::getId).toList());
641	        BigDecimal rate = taxRate.percent();
642	        for (Invoice i : list) {
643	            LocalDate on = i.paidOn(found, rate);
644	            if (on != null) {
645	                paidOn.put(i.getId(), on);
646	            }
647	        }
648	        return paidOn;
649	    }
650	
651	    /** What has been paid to each of the invoices; an invoice paid nothing is paid zero. */
652	    @Transactional(readOnly = true)
653	    public Map<Long, BigDecimal> paid(List<Invoice> list) {
654	        Map<Long, BigDecimal> paid = new HashMap<>();
655	        list.forEach(i -> paid.put(i.getId(), BigDecimal.ZERO.setScale(2)));
656	        if (!list.isEmpty()) {
657	            for (Object[] row : payments.paidTo(list.stream().map(Invoice::getId).toList())) {
658	                paid.put((Long) row[0], ((BigDecimal) row[1]).setScale(2));
659	            }
660	        }
661	        return paid;
662	    }
663	
664	    /**
665	     * Records a payment of the amount on the date against a sent invoice that still has something
666	     * due, and records it in the audit; empty if no such invoice. The amount has already been
667	     * checked; what it pays beyond what is due is held on the client's account as credit. A draft, an
668	     * invoice already paid, or a date after today
669	     * or before the invoice's issue date is refused. The reference (null when none was quoted) has
670	     * already been checked; one that belongs to a different invoice is refused.
671	     */
672	    @Transactional
673	    public Optional<Invoice> recordPayment(Long invoiceId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
674	            String reference) {
675	        Optional<Invoice> found = invoices.findWithLinesById(invoiceId);
676	        found.ifPresent(invoice -> {
677	            if (invoice.isDraft()) {
678	                throw new InvoiceRejectedException("Send the invoice before recording a payment.");
679	            }
680	            if (invoice.isVoid()) {
681	                throw new InvoiceRejectedException("A void invoice takes no payments.");
682	            }
683	            if (invoice.isCreditNote()) {
684	                throw new InvoiceRejectedException("A credit note takes no payments.");
685	            }
686	            BigDecimal amount = converted(paidAmount, paidIn, invoice.currency());
687	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
688	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
689	            if (due.signum() <= 0) {
690	                throw new InvoiceRejectedException("This invoice has already been paid.");
691	            }
692	            BigDecimal applied = amount.min(due);
693	            if (invoice.hasPlan() && invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
694	                throw new InvoiceRejectedException("A payment must be at least the "
695	                        + invoice.currency().format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
696	                        + " still unpaid on the earliest unpaid instalment, unless it settles the plan.");
697	            }
698	            if (invoice.isTooSmallPart(applied, paidSoFar, taxRate.percent())) {
699	                throw new InvoiceRejectedException("A part payment must be at least "
700	                        + invoice.currency().format(invoice.minimumPart(taxRate.percent()))
701	                        + " (10% of the total), unless it settles the invoice.");
702	            }
703	            LocalDate now = today.date();
704	            if (date.isAfter(now)) {
705	                throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
706	            }
707	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
708	                throw new InvoiceRejectedException(
709	                        "The payment date cannot be before the invoice's issue date (" + invoice.getIssueDate() + ").");
710	            }
711	            if (reference != null && !reference.equals(PaymentReference.of(invoice.getId()))) {
712	                throw new InvoiceRejectedException(PaymentReference.grouped(reference)
713	                        + " is the reference of a different invoice; this invoice's is "
714	                        + PaymentReference.grouped(PaymentReference.of(invoice.getId())) + ".");
715	            }
716	            Payment payment = payments.saveAndFlush(Payment.against(invoice, amount, applied, date, reference)
717	                    .paidIn(paidIn, paidAmount, invoice.currency()));
718	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + invoice.getId() + " amount="
719	                    + applied.setScale(invoice.scale(), RoundingMode.UNNECESSARY).toPlainString());
720	            recordWriteOff(invoice);
721	            recordCreditHeld(payment);
722	        });
723	        return found;
724	    }
725	
726	    /**
727	     * Records one payment of the amount on the date against the client's unpaid sent invoices, earliest
728	     * due date first (lower id first on the same due date) so overdue invoices are cleared first,
729	     * paying each off in full before the next.
730	     * What it pays beyond everything the client owes is held on the client's account as credit; the
731	     * rest is checked and recorded as a split payment over the invoices it reaches.
732	     * References (empty when none, each already checked) instead limit the payment to the client's
733	     * invoices with those references, applied in the same order; one that is not the reference of any
734	     * of the client's invoices is refused; what is paid beyond what those invoices owe together is held
735	     * as credit.
736	     * The payment keeps the reference of the first invoice it reaches.
737	     */
738	    @Transactional
739	    public Payment recordAutoPayment(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
740	            List<String> references) {
741	        BigDecimal amount = converted(paidAmount, paidIn, currencyOf(clientId));
742	        List<Invoice> ofClient = invoices.findByClientIdOrderByIdAsc(clientId);
743	        List<Invoice> candidates = ofClient;
744	        if (!references.isEmpty()) {
745	            Set<Long> named = new HashSet<>();
746	            for (String reference : references) {
747	                Invoice invoice = ofClient.stream()
748	                        .filter(i -> reference.equals(PaymentReference.of(i.getId())))
749	                        .findFirst()
750	                        .orElseThrow(() -> new InvoiceRejectedException(PaymentReference.grouped(reference)
751	                                + " is not the reference of any of this client's invoices."));
752	                String number = InvoiceNumber.of(invoice.getId());
753	                if (invoice.isDraft()) {
754	                    throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
755	                }
756	                if (invoice.isVoid()) {
757	                    throw new InvoiceRejectedException(number + " is void and takes no payments.");
758	                }
759	                if (invoice.isCreditNote()) {
760	                    throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
761	                }
762	                named.add(invoice.getId());
763	            }
764	            candidates = ofClient.stream().filter(i -> named.contains(i.getId())).toList();
765	        }
766	        List<Invoice> sent = candidates.stream()
767	                .filter(i -> !i.isDraft() && !i.isVoid() && !i.isCreditNote())
768	                .sorted(Comparator.comparing(Invoice::getDueDate, Comparator.nullsLast(Comparator.naturalOrder()))
769	                        .thenComparing(Invoice::getId))
770	                .toList();
771	        Map<Long, BigDecimal> paid = paid(sent);
772	        BigDecimal owed = BigDecimal.ZERO;
773	        BigDecimal left = amount;
774	        List<PaymentAllocation> parts = new ArrayList<>();
775	        for (Invoice invoice : sent) {
776	            BigDecimal due = invoice.amountDue(paid.get(invoice.getId()), taxRate.percent());
777	            if (due.signum() <= 0) {
778	                continue;
779	            }
780	            owed = owed.add(due);
781	            if (left.signum() > 0) {
782	                BigDecimal part = left.min(due);
783	                parts.add(new PaymentAllocation(invoice.getId(), part));
784	                left = left.subtract(part);
785	            }
786	        }
787	        if (owed.signum() <= 0) {
788	            throw new InvoiceRejectedException(references.isEmpty() ? "The client has no unpaid invoices to pay."
789	                    : "Those invoices have already been paid.");
790	        }
791	        String reference = references.isEmpty() ? null : PaymentReference.of(parts.get(0).getInvoiceId());
792	        return recordSpread(clientId, amount, paidAmount, paidIn, date, reference, parts, true);
793	    }
794	
795	    /**
796	     * Records one payment of the amount on the date spread over several of the client's invoices, and
797	     * records each part in the audit. The amounts have already been checked to be more than zero; they
798	     * must add up exactly to the payment, and each must go to a different sent invoice of the client
799	     * and be no more than what it still has due. The date must be no later than today nor before any
800	     * of the invoices' issue dates. The reference (null when none) has already been checked; it must
801	     * be the reference of one of the invoices.
802	     */
803	    @Transactional
804	    public Payment recordSplitPayment(Long clientId, BigDecimal paidAmount, Currency paidIn, LocalDate date,
805	            String reference, List<PaymentAllocation> parts) {
806	        BigDecimal amount = converted(paidAmount, paidIn, currencyOf(clientId));
807	        return recordSpread(clientId, amount, paidAmount, paidIn, date, reference, parts, false);
808	    }
809	
810	    /**
811	     * Records the payment spread over the parts as {@link #recordSplitPayment} does, except that when
812	     * credit may be held the parts may add up to less than the payment: the rest is held on the
813	     * client's account as credit and recorded in the audit.
814	     */
815	    private Payment recordSpread(Long clientId, BigDecimal amount, BigDecimal paidAmount, Currency paidIn,
816	            LocalDate date, String reference, List<PaymentAllocation> parts, boolean holdCredit) {
817	        if (parts.isEmpty()) {
818	            throw new InvoiceRejectedException("Enter how much of the payment goes to each invoice.");
819	        }
820	        Currency currency = currencyOf(clientId);
821	        requireWhole(currency, amount, "The amount");
822	        for (PaymentAllocation part : parts) {
823	            requireWhole(currency, part.getAmount(), "Each invoice's part");
824	        }
825	        BigDecimal sum = parts.stream().map(PaymentAllocation::getAmount).reduce(BigDecimal.ZERO, BigDecimal::add);
826	        if (holdCredit ? sum.compareTo(amount) > 0 : sum.compareTo(amount) != 0) {
827	            throw new InvoiceRejectedException("The amounts for the invoices add up to "
828	                    + currency.format(sum) + ", not the " + currency.format(amount) + " paid.");
829	        }
830	        LocalDate now = today.date();
831	        if (date.isAfter(now)) {
832	            throw new InvoiceRejectedException("The payment date cannot be after today (" + now + ").");
833	        }
834	        Set<Long> seen = new HashSet<>();
835	        List<Invoice> spreadOver = new ArrayList<>();
836	        for (PaymentAllocation part : parts) {
837	            if (!seen.add(part.getInvoiceId())) {
838	                throw new InvoiceRejectedException("Each invoice can take only one part of the payment.");
839	            }
840	            Invoice invoice = invoices.findWithLinesById(part.getInvoiceId())
841	                    .filter(i -> i.getClientId().equals(clientId))
842	                    .orElseThrow(() -> new InvoiceRejectedException("A part of the payment goes to an invoice of another client."));
843	            String number = InvoiceNumber.of(invoice.getId());
844	            if (invoice.isDraft()) {
845	                throw new InvoiceRejectedException("Send " + number + " before recording a payment against it.");
846	            }
847	            if (invoice.isVoid()) {
848	                throw new InvoiceRejectedException(number + " is void and takes no payments.");
849	            }
850	            if (invoice.isCreditNote()) {
851	                throw new InvoiceRejectedException(invoice.number() + " is a credit note and takes no payments.");
852	            }
853	            BigDecimal paidSoFar = paid(List.of(invoice)).get(invoice.getId());
854	            BigDecimal due = invoice.amountDue(paidSoFar, taxRate.percent());
855	            if (part.getAmount().compareTo(due) > 0) {
856	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
857	                        + number + " is more than the " + currency.format(due) + " it has due.");
858	            }
859	            if (invoice.hasPlan() && invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
860	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
861	                        + number + " is less than the " + currency.format(invoice.earliestUnpaid(paidSoFar, taxRate.percent()))
862	                        + " still unpaid on its earliest unpaid instalment, unless it settles the plan.");
863	            }
864	            if (invoice.isTooSmallPart(part.getAmount(), paidSoFar, taxRate.percent())) {
865	                throw new InvoiceRejectedException("The " + currency.format(part.getAmount()) + " for "
866	                        + number + " is less than " + currency.format(invoice.minimumPart(taxRate.percent()))
867	                        + " (10% of its total), unless it settles the invoice.");
868	            }
869	            if (invoice.getIssueDate() != null && date.isBefore(invoice.getIssueDate())) {
870	                throw new InvoiceRejectedException("The payment date cannot be before the issue date of " + number
871	                        + " (" + invoice.getIssueDate() + ").");
872	            }
873	            spreadOver.add(invoice);
874	        }
875	        if (reference != null && spreadOver.stream().noneMatch(i -> reference.equals(PaymentReference.of(i.getId())))) {
876	            throw new InvoiceRejectedException(PaymentReference.grouped(reference)
877	                    + " is not the reference of any of the invoices being paid.");
878	        }
879	        Payment payment = payments.saveAndFlush(Payment.split(clientId, amount, date, reference, parts)
880	                .paidIn(paidIn, paidAmount, currency));
881	        for (PaymentAllocation part : parts) {
882	            audit.record("PAYMENT_RECORDED id=" + payment.getId() + " invoice=" + part.getInvoiceId() + " amount="
883	                    + part.getAmount().setScale(currency.scale(), RoundingMode.UNNECESSARY).toPlainString());
884	        }
885	        spreadOver.forEach(this::recordWriteOff);
886	        recordCreditHeld(payment);
887	        return payment;
888	    }
889	
890	    /**
891	     * The amount paid in the currency (null for the client's own) converted into the client's currency
892	     * through US dollars at the workspace rates; this is what is applied and checked. The amount must be
893	     * whole in the currency it was paid in, and must still be more than zero once converted.
894	     */
895	    private BigDecimal converted(BigDecimal paidAmount, Currency paidIn, Currency clientCurrency) {
896	        Currency from = paidIn == null ? clientCurrency : paidIn;
897	        requireWhole(from, paidAmount, "The amount");
898	        BigDecimal amount = exchangeRates.convert(paidAmount, from, clientCurrency);
899	        if (amount.signum() <= 0) {
900	            throw new InvoiceRejectedException("The amount is worth nothing once converted into "
901	                    + clientCurrency.name() + ".");
902	        }
903	        return amount;
904	    }
905	
906	    /** The currency the client is billed in; US dollars when there is no such client. */
907	    private Currency currencyOf(Long clientId) {
908	        return clients.findById(clientId).map(Client::getCurrency).orElse(Currency.USD);
909	    }
910	
911	    /**
912	     * Refuses an amount entered with more decimals than the currency has: whole yen for a yen client
913	     * (the cent is already checked for the rest).
914	     */
915	    private static void requireWhole(Currency currency, BigDecimal amount, String what) {
916	        if (amount != null && !currency.isWhole(amount)) {
917	            throw new InvoiceRejectedException(what + " must be in whole yen, with no decimals.");
918	        }
919	    }
920	
921	    /** Records in the audit what a payment just recorded holds on the client's account as credit, if anything. */
922	    private void recordCreditHeld(Payment payment) {
923	        BigDecimal credit = payment.credit();
924	        if (credit.signum() > 0) {
925	            audit.record("CREDIT_HELD payment=" + payment.getId() + " amount="
926	                    + credit.setScale(currencyOf(payment.getClientId()).scale(), RoundingMode.UNNECESSARY).toPlainString());
927	        }
928	    }
929	
930	    /** Records in the audit what a payment just recorded left written off on the invoice, if anything. */
931	    private void recordWriteOff(Invoice invoice) {
932	        BigDecimal writtenOff = invoice.writtenOff(paid(List.of(invoice)).get(invoice.getId()), taxRate.percent());
933	        if (writtenOff.signum() > 0) {
934	            audit.record("INVOICE_WRITTEN_OFF id=" + invoice.getId() + " amount=" + writtenOff.toPlainString());
935	        }
936	    }
937	
938	    /**
939	     * Reverses the payment (a bounced cheque), undoing it on every invoice it was applied to, and
940	     * records it in the audit; empty if no such payment. A payment already reversed, or one that has
941	     * had any of its credit refunded, or credit from a credit note, is refused.
942	     */
943	    @Transactional
944	    public Optional<Payment> reversePayment(Long paymentId) {
945	        Optional<Payment> found = payments.findById(paymentId);
946	        found.ifPresent(payment -> {
947	            if (payment.isReversed()) {
948	                throw new InvoiceRejectedException("This payment has already been reversed.");
949	            }
950	            if (payment.getCreditNote() != null) {
951	                throw new InvoiceRejectedException("This is credit from a credit note, so it cannot be reversed.");
952	            }
953	            if (payment.getRefunded().signum() > 0) {
954	                throw new InvoiceRejectedException("This payment has had credit refunded, so it cannot be reversed.");
955	            }
956	            payment.reverse();
957	            payments.saveAndFlush(payment);
958	            audit.record("PAYMENT_REVERSED id=" + payment.getId() + " amount="
959	                    + payment.getAmount().setScale(currencyOf(payment.getClientId()).scale(), RoundingMode.UNNECESSARY)
960	                            .toPlainString());
961	        });
962	        return found;
963	    }
964	}
